export function animate(canvas: HTMLCanvasElement, balls: any[], isPaused: () => boolean, setFrameCount: (n: number) => void) {
  let lastTime = Date.now();
  let frameCount = 0;

  function step() {
    if (!isPaused()) {
      const now = Date.now();
      lastTime = now;

      for (const b of balls) {
        b.vy += 0.2;
        b.x += b.vx;
        b.y += b.vy;

        if (b.x - b.r < 0) {
          b.x = b.r;
          b.vx = -b.vx;
        }
        if (b.x + b.r > 400) {
          b.x = 400 - b.r;
          b.vx = -b.vx;
        }
        if (b.y - b.r < 0) {
          b.y = b.r;
          b.vy = -b.vy;
        }
        if (b.y + b.r > 300) {
          b.y = 300 - b.r;
          b.vy = -b.vy;
        }
      }

      for (let i = 0; i < balls.length; i++) {
        for (let j = i + 1; j < balls.length; j++) {
          const b1 = balls[i];
          const b2 = balls[j];
          const dx = b2.x - b1.x;
          const dy = b2.y - b1.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < b1.r + b2.r) {
            const tempVx = b1.vx;
            b1.vx = b2.vx;
            b2.vx = tempVx;
            const tempVy = b1.vy;
            b1.vy = b2.vy;
            b2.vy = tempVy;
          }
        }
      }

      const ctx = canvas.getContext("2d")!;
      ctx.fillStyle = "#fff";
      ctx.fillRect(0, 0, 400, 300);
      ctx.fillStyle = "#000";
      for (const b of balls) {
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
        ctx.fill();
      }

      frameCount++;
      setFrameCount(frameCount);
    }

    requestAnimationFrame(step);
  }

  requestAnimationFrame(step);
}

