model Ball {
  x: Number
  y: Number
  vx: Number
  vy: Number
  radius: Number
}

component Sim {
  state balls: Ball[] = []
  state paused = false
  state frameCount = 0
  ref canvas
  ref animationId

  fn initBalls() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push({
        x: Math.random() * 380 + 10,
        y: Math.random() * 280 + 10,
        vx: Math.random() * 4 - 2,
        vy: Math.random() * 4 - 2,
        radius: 10
      })
    }
    frameCount = 0
  }

  fn addBall() {
    balls.push({
      x: Math.random() * 380 + 10,
      y: Math.random() * 280 + 10,
      vx: Math.random() * 4 - 2,
      vy: Math.random() * 4 - 2,
      radius: 10
    })
  }

  fn applyGravity() {
    for b in balls {
      b.vy += 0.2
    }
  }

  fn checkBounds() {
    for b in balls {
      if b.x - b.radius < 0 {
        b.x = b.radius
        b.vx = -b.vx
      }
      if b.x + b.radius > 400 {
        b.x = 400 - b.radius
        b.vx = -b.vx
      }
      if b.y - b.radius < 0 {
        b.y = b.radius
        b.vy = -b.vy
      }
      if b.y + b.radius > 300 {
        b.y = 300 - b.radius
        b.vy = -b.vy
      }
    }
  }

  fn checkCollisions() {
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let b1 = balls[i]
        let b2 = balls[j]
        let dx = b2.x - b1.x
        let dy = b2.y - b1.y
        let dist = Math.sqrt(dx * dx + dy * dy)
        let minDist = b1.radius + b2.radius

        if dist < minDist {
          let temp = b1.vx
          b1.vx = b2.vx
          b2.vx = temp

          temp = b1.vy
          b1.vy = b2.vy
          b2.vy = temp

          let overlap = minDist - dist
          let nx = dx / dist
          let ny = dy / dist
          b1.x -= nx * overlap * 0.5
          b1.y -= ny * overlap * 0.5
          b2.x += nx * overlap * 0.5
          b2.y += ny * overlap * 0.5
        }
      }
    }
  }

  fn updatePhysics() {
    applyGravity()

    for b in balls {
      b.x += b.vx
      b.y += b.vy
    }

    checkBounds()
    checkCollisions()
  }

  fn draw() {
    let ctx = canvas.getContext("2d")
    ctx.fillStyle = "white"
    ctx.fillRect(0, 0, 400, 300)
    ctx.fillStyle = "blue"
    ctx.strokeStyle = "darkblue"
    ctx.lineWidth = 2

    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2)
      ctx.fill()
      ctx.stroke()
    }
  }

  fn animate() {
    if !paused {
      updatePhysics()
      frameCount++
    }
    draw()
    animationId = requestAnimationFrame(animate)
  }

  fn togglePause() {
    paused = !paused
  }

  fn restart() {
    initBalls()
  }

  mount {
    initBalls()
    draw()
    animationId = requestAnimationFrame(animate)
    cleanup {
      cancelAnimationFrame(animationId)
    }
  }

  column gap=4 pad=4 {
    row gap=2 {
      button "Agregar" -> addBall()
      button (paused ? "Reanudar" : "Pausar") primary -> togglePause()
      button "Reiniciar" danger -> restart()
    }
    row gap=4 {
      text `Pelotas: ${balls.length}` bold
      text `Cuadros: ${frameCount}` bold
    }
    canvas ref=canvas width=400 height=300 style="border: 1px solid #ccc; background: white; display: block;"
  }
}

