fn getInitials(name: String) {
  let parts = name.split(" ")
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
}

fn getColorForName(name: String) {
  let colors = ["#FF6B6B", "#4ECDC4", "#45B7D1", "#FFA07A", "#98D8C8", "#F7DC6F", "#BB8FCE", "#85C1E2"]
  let code = name.charCodeAt(0) + name.charCodeAt(name.length - 1)
  return colors[code % colors.length]
}

fn formatBudget(amount: Number) {
  return new Intl.NumberFormat("es-ES", { style: "currency", currency: "USD", minimumFractionDigits: 0 }).format(amount)
}

fn formatArrival(date: String) {
  return format(new Date(date + "T00:00:00"), "dd/MM/yyyy")
}

